float sdCircle( vec2 p, float r )
{
    return length(p) - r;
}
float sdBox( in vec2 p, in vec2 b )
{
    vec2 d = abs(p)-b;
    return length(max(d,0.0)) + min(max(d.x,d.y),0.0);
}
float ndot(vec2 a, vec2 b ) { return a.x*b.x - a.y*b.y; }
float sdRhombus( in vec2 p, in vec2 b ) 
{
    p = abs(p);
    float h = clamp( ndot(b-2.0*p,b)/dot(b,b), -1.0, 1.0 );
    float d = length( p-0.5*b*vec2(1.0-h,1.0+h) );
    return d * sign( p.x*b.y + p.y*b.x - b.x*b.y );
}
float sdParallelogram( in vec2 p, float wi, float he, float sk )
{
    vec2 e = vec2(sk,he);
    p = (p.y<0.0)?-p:p;
    vec2  w = p - e; w.x -= clamp(w.x,-wi,wi);
    vec2  d = vec2(dot(w,w), -w.y);
    float s = p.x*e.y - p.y*e.x;
    p = (s<0.0)?-p:p;
    vec2  v = p - vec2(wi,0); v -= e*clamp(dot(v,e)/dot(e,e),-1.0,1.0);
    d = min( d, vec2(dot(v,v), wi*he-abs(s)));
    return sqrt(d.x)*sign(-d.y);
}
float sdEquilateralTriangle( in vec2 p, in float r )
{
    const float k = sqrt(3.0);
    p.x = abs(p.x) - r;
    p.y = p.y + r/k;
    if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
    p.x -= clamp( p.x, -2.0*r, 0.0 );
    return -length(p)*sign(p.y);
}
float sdUnevenCapsule( vec2 p, float r1, float r2, float h )
{
    p.x = abs(p.x);
    float b = (r1-r2)/h;
    float a = sqrt(1.0-b*b);
    float k = dot(p,vec2(-b,a));
    if( k < 0.0 ) return length(p) - r1;
    if( k > a*h ) return length(p-vec2(0.0,h)) - r2;
    return dot(p, vec2(a,b) ) - r1;
}
float sdHexagon( in vec2 p, in float r )
{
    const vec3 k = vec3(-0.866025404,0.5,0.577350269);
    p = abs(p);
    p -= 2.0*min(dot(k.xy,p),0.0)*k.xy;
    p -= vec2(clamp(p.x, -k.z*r, k.z*r), r);
    return length(p)*sign(p.y);
}
float sdStar5(in vec2 p, in float r, in float rf)
{
    const vec2 k1 = vec2(0.809016994375, -0.587785252292);
    const vec2 k2 = vec2(-k1.x,k1.y);
    p.x = abs(p.x);
    p -= 2.0*max(dot(k1,p),0.0)*k1;
    p -= 2.0*max(dot(k2,p),0.0)*k2;
    p.x = abs(p.x);
    p.y -= r;
    vec2 ba = rf*vec2(-k1.y,k1.x) - vec2(0,1);
    float h = clamp( dot(p,ba)/dot(ba,ba), 0.0, r );
    return length(p-ba*h) * sign(p.y*ba.x-p.x*ba.y);
}
float sdPie( in vec2 p, in vec2 c, in float r )
{
    p.x = abs(p.x);
    float l = length(p) - r;
    float m = length(p-c*clamp(dot(p,c),0.0,r));
    return max(l,m*sign(c.y*p.x-c.x*p.y));
}
float sdMoon(vec2 p, float d, float ra, float rb )
{
    p.y = abs(p.y);
    float a = (ra*ra - rb*rb + d*d)/(2.0*d);
    float b = sqrt(max(ra*ra-a*a,0.0));
    if( d*(p.x*b-p.y*a) > d*d*max(b-p.y,0.0) )
          return length(p-vec2(a,b));
    return max( (length(p          )-ra),
               -(length(p-vec2(d,0))-rb));
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
vec2 uv = fragCoord / iResolution.xy;
uv = uv * 2.0 - 1.0;
uv.x = uv.x * iResolution.x / iResolution.y;

vec3 circle = vec3(step(0.0, sdCircle(uv - vec2(0.0, 0.0), 0.1)));
vec3 square = vec3(step(0.0, sdBox(uv - vec2(-1.2, 0.9), vec2(0.2, 0.1))));
vec3 rhombus = vec3(step(0.0, sdRhombus(uv - vec2(-1.5, 0.7), vec2(0.2, 0.1))));
vec3 parallelogram = vec3(step(0.0, sdParallelogram(uv - vec2(-1.5, 0.4), 0.1, 0.1, 0.1)));
vec3 equilateralTriangle = vec3(step(0.0, sdEquilateralTriangle(uv - vec2(-1.5, 0.1), 0.1)));
vec3 unevenCapsule = vec3(step(0.0, sdUnevenCapsule(uv - vec2(-1.5, -0.4), 0.1, 0.1, 0.2)));
vec3 hexagon = vec3(step(0.0, sdHexagon(uv - vec2(-1.1, 0.4), 0.2)));
vec3 star5 = vec3(step(0.0, sdStar5(uv - vec2(-1.1, -0.1), 0.2, 0.5)));
vec3 pie = vec3(step(0.0, sdPie(uv - vec2(-1.1, -0.5), vec2(-0.2, 0.1), 0.2)));
vec3 moon = vec3(step(0.0, sdMoon(uv - vec2(-1.5, -0.8), 0.1, 0.2, 0.15)));
vec3 shape = min(circle, square);
shape = min(shape, rhombus);
shape = min(shape, parallelogram);
shape = min(shape, equilateralTriangle);
shape = min(shape, unevenCapsule);
shape = min(shape, hexagon);
shape = min(shape, star5);
shape = min(shape, pie);
shape = min(shape, moon);
fragColor = vec4(shape, 1.0);
//fragColor = vec4(rhombus, 1.0);
}
